package estate.api;

import java.sql.Connection;
import java.util.Map;

/** What the platform gives an instance. The database is shared by every instance and every version of the service. */
public interface Context {
    Connection db();

    /** Synchronous call to another service. Throws ServiceException with code "timeout", "unavailable" or "error". */
    Map<String, String> call(String service, String op, Map<String, String> request) throws ServiceException;

    /** Publish an event; consumers receive it a few ticks later. */
    void publish(String topic, Map<String, String> event);

    /** Platform clock (ticks). */
    long now();
}
package estate.api;

import java.util.Map;

/** A deployable service. One instance of the implementing class runs per deployed instance of the service. */
public interface Service {
    /** Called once when an instance starts. Run your schema migrations here. */
    void start(Context ctx) throws Exception;

    /** Handle a synchronous request. `op` and the maps are the service's published contract. */
    Map<String, String> handle(String op, Map<String, String> req) throws ServiceException;

    /** Handle an asynchronous event from a topic this service subscribes to. */
    default void onEvent(String topic, Map<String, String> event) throws Exception {}
}
package estate.api;

public class ServiceException extends Exception {
    public final String code;

    public ServiceException(String code, String message) {
        super(message);
        this.code = code;
    }
}
